import { YearPicker } from '@absoluteui/components/year-picker';

const host = document.createElement('div');
document.body.append(host);
const picker = YearPicker.create(host, {
  label: 'Model year',
  name: 'modelYear',
  required: true,
  min: 1990,
  max: 2027,
});
host.addEventListener('aui-change', () => {
  host.dataset.valid = String(picker.validity.valid);
});

import { YearPicker, type YearPickerChangeDetail } from '@absoluteui/components/year-picker';

const closedYears = new Set([2020, 2021]);
const host = document.createElement('div');
document.body.append(host);
YearPicker.create(host, {
  label: 'Tax year',
  value: 2025,
  isYearDisabled: (year) => closedYears.has(year),
  validate: (year) => (year !== null && year > 2026 ? 'Future years cannot be filed.' : null),
});
host.addEventListener('aui-change', (event) => {
  const { value, validity } = (event as CustomEvent<YearPickerChangeDetail>).detail;
  host.dataset.year = value === null ? '' : String(value);
  host.dataset.error = validity.error ?? '';
});

